llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, the closest structural analogue sharing the N-cyclopropylmethyl and 3,14-diol morphinan core, has an absolute oral bioavailability of 41% in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Morphine, a 3,6-diol morphinan, has a mean absolute oral bioavailability of 47.1% (range 29.9–69.3%) in patients, showing that a 6-hydroxy group is compatible with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Samidorphan, an N-cyclopropylmethyl 3,14-diol morphinan with a C6 oxygen substituent, has an absolute oral bioavailability of 68.6%, supporting adequate oral absorption for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Naldemedine, a C6-substituted N-cyclopropylmethyl morphinan, has an estimated absolute oral bioavailability of 20–56%, consistent with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Naltrexone, the 6-keto analogue, has a reported absolute oral bioavailability of 5%, which is contradictory; however, its low F is driven largely by first-pass ketone reduction to the 6-hydroxy metabolite, a pathway not applicable to the query because the 6-hydroxy group is already present.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Butorphanol, a 3,14-diol morphinan without a C6 oxygen, has low oral bioavailability of 5–17%, but its N-cyclobutylmethyl group and lack of the C6 hydroxy substituent make it less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is a 6-hydroxy N-cyclopropylmethyl morphinan (naltrexol-like). The closest high-bioavailability analogues nalmefene (41–53%) and samidorphan (69%) support F ≥ 20%, and morphine's 6-hydroxy morphinan data confirm that a C6 hydroxyl does not preclude adequate oral bioavailability. Low-F naltrexone and butorphanol are less transferable because of different C6 functionality and first-pass pathways.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query or naltrexol itself.",
    "The extent of first-pass glucuronidation at the 6-hydroxy group in the query is not directly quantified.",
    "Naltrexone's low oral bioavailability introduces uncertainty because it is a close structural analogue, even though its main first-pass pathway is not applicable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

